('program','img/program-seni.jpg','','Seni & Kreativitas','Mengembangkan ekspresi diri melalui melukis, mewarnai, kolase, dan berbagai kegiatan seni kreatif.','',0,NULL,'',1),
('program','img/program-calistung.jpg','','Calistung Fun','Belajar membaca, menulis, dan berhitung dengan metode bermain yang menyenangkan dan efektif.','',0,NULL,'',2),
('program','img/program-karakter.jpg','','Karakter & Moral','Menanamkan sopan santun, kejujuran, dan tanggung jawab sejak usia dini.','',0,NULL,'',3),
('program','img/program-motorik.jpg','','Motorik & Gerak','Senam, permainan outdoor, dan aktivitas fisik untuk tumbuh kembang optimal.','',0,NULL,'',4),
('program','img/program-menyanyi.jpg','','Menyanyi','Mengembangkan kemampuan vokal dan rasa percaya diri anak melalui kegiatan menyanyi bersama.','',0,NULL,'',5),
('program','img/program-inggris.jpg','','Bahasa Inggris','Pengenalan bahasa Inggris sejak dini dengan metode interaktif yang menyenangkan.','',0,NULL,'',6),
('beranda_faq','','','Berapa usia minimal untuk mendaftar?','Kelompok Bermain (KB) untuk anak usia 3–4 tahun, TK A untuk usia 4–5 tahun, dan TK B untuk usia 5–6 tahun.','',0,NULL,'',1),
('beranda_faq','','','Bagaimana cara mendaftar?','Hubungi kami melalui WhatsApp di 0819-3258-7866 atau datang langsung ke sekolah. Kami akan menjelaskan persyaratan dan jadwal pendaftaran.','',0,NULL,'',2),
('beranda_faq','','','Kapan jam belajar di sekolah?','Kegiatan belajar berlangsung Senin sampai Sabtu, pukul 07.00 – 12.00 WIB.','',0,NULL,'',3),
('beranda_faq','','','Berapa biaya pendaftaran dan uang sekolah?','Untuk informasi biaya terbaru, silakan hubungi kami via WhatsApp agar mendapat penjelasan yang akurat.','',0,NULL,'',4),
('beranda_faq','','','Apakah sekolah sudah terakreditasi?','Ya, KB & TK Santa Anna Sragen terakreditasi A oleh BAN-PAUD.','',0,NULL,'',5),
('beranda_faq','','','Di mana lokasi sekolah?','Jalan Rokan No. 15 Sragen Tengah, Kabupaten Sragen, Jawa Tengah 57211. Peta lengkap ada di halaman Hubungi Kami.','',0,NULL,'',6),
('beranda_testimoni','','','Nama Orang Tua','Tulis testimoni orang tua murid di sini. Ganti teks ini dengan kesan dan pesan yang sebenarnya.','Orang tua murid TK A',5,NULL,'',1),
('beranda_testimoni','','','Nama Orang Tua','Tulis testimoni orang tua murid di sini. Ganti teks ini dengan kesan dan pesan yang sebenarnya.','Orang tua murid TK B',5,NULL,'',2),
